+    display: flex;
+    align-items: center;
+    justify-content: center;
+    height: 100%;
+    color: #72767d;
+    font-size: 1.1rem;
+}
+
+/* Message List */
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 16px 20px;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 12px;
+    color: #8e9297;
+    font-size: 0.85rem;
+}
+
+/* Message Item */
+.message-item {
+    padding: 8px 12px;
+    border-radius: 4px;
+    position: relative;
+    margin-bottom: 4px;
+    transition: background 0.1s;
+}
+
+.message-item.hovered {
+    background: #32353b;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 4px;
+}
+
+.message-author {
+    font-weight: 600;
+    color: #fff;
+    font-size: 0.9rem;
+}
+
+.message-time {
+    font-size: 0.7rem;
+    color: #72767d;
+}
+
+.message-content {
+    font-size: 0.9rem;
+    line-height: 1.4;
+    word-wrap: break-word;
+}
+
+/* Reactions */
+.message-reactions {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 4px;
+    margin-top: 6px;
+}
+
+.reaction-badge {
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 2px 8px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.reaction-badge:hover {
+    background: #3c3f44;
+    border-color: #7289da;
+}
+
+/* Thread Link */
+.thread-link {
+    margin-top: 6px;
+    font-size: 0.8rem;
+    color: #7289da;
+    cursor: pointer;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+/* Message Actions */
+.message-actions {
+    position: absolute;
+    top: -8px;
+    right: 12px;
+    display: flex;
+    gap: 4px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 4px;
+    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
+}
+
+.btn-action {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 0.75rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 3px;
+    white-space: nowrap;
+}
+
+.btn-action:hover {
+    background: #36393f;
+    color: #fff;
+}
+
+/* Emoji Picker */
+.emoji-picker {
+    position: absolute;
+    top: -8px;
+    right: 140px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 6px;
+    padding: 8px;
+    display: flex;
+    gap: 6px;
+    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
+}
+
+.emoji-option {
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+    transition: background 0.1s;
+}
+
+.emoji-option:hover {
+    background: #36393f;
+}
+
+/* Message Input */
+.message-input {
+    padding: 12px 20px;
+    border-top: 1px solid #202225;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+    flex-shrink: 0;
+}
+
+.message-input textarea {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 6px;
+    color: #dcddde;
+    padding: 10px 14px;
+    font-size: 0.9rem;
+    font-family: inherit;
+    resize: none;
+    outline: none;
+}
+
+.message-input textarea::placeholder {
+    color: #72767d;
+}
+
+.btn-send {
+    background: #7289da;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 18px;
+    font-weight: 600;
+    cursor: pointer;
+    font-size: 0.85rem;
+    transition: background 0.15s;
+}
+
+.btn-send:hover:not(:disabled) {
+    background: #677bc4;
+}
+
+.btn-send:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #202225;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+.btn-close-thread {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.btn-close-thread:hover {
+    background: #36393f;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    background: #36393f;
+    border-radius: 4px;
+    margin: 12px;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    margin-top: 4px;
+    font-size: 0.85rem;
+}
+
+.thread-divider {
+    padding: 8px 16px;
+    font-size: 0.75rem;
+    color: #8e9297;
+    border-bottom: 1px solid #4f545c;
+    margin: 0 12px;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+.thread-reply {
+    padding: 8px 0;
+    border-bottom: 1px solid #3c3f44;
+}
+
+.thread-reply:last-child {
+    border-bottom: none;
+}
+

